def count_primes_in_range(a, b):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    return sum(1 for x in range(a, b + 1) if is_prime(x))

def sum_of_prime_factors(n):
    total = 0
    x = n
    p = 2
    while p * p <= x:
        if x % p == 0:
            total += p
            while x % p == 0:
                x //= p
        p += 1
    if x > 1:
        total += x
    return total

