    if len(sa) != len(sb):
        return False
    return sb in (sa + sa)

def is_perfect_cube(n):
    x = abs(n)
    lo, hi = 0, max(1, x)
    while lo < hi:
        mid = (lo + hi) // 2
        if mid ** 3 < x:
            lo = mid + 1
        else:
            hi = mid
    return lo ** 3 == x

def cube_root_floor(n):
    lo, hi = 0, max(1, n)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid ** 3 <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

