def count_perfect_numbers_in_range(a, b):
    def proper_sum(x):
        if x <= 1:
            return 0
        total = 1
        i = 2
        while i * i <= x:
            if x % i == 0:
                total += i
                if i != x // i:
                    total += x // i
            i += 1
        return total
    count = 0
    for x in range(max(a, 1), b + 1):
        if x > 1 and proper_sum(x) == x:
            count += 1
    return count

def count_semiprimes_in_range(a, b):
    def is_semiprime(x):
        count = 0
        n = x
        p = 2
        while p * p <= n:
            while n % p == 0:
                n //= p
                count += 1
                if count > 2:
                    return False
            p += 1
        if n > 1:
            count += 1
        return count == 2
    return sum(1 for x in range(a, b + 1) if is_semiprime(x))
